package ca

import "math/big"

// rocaPrimes are the primes of the ROCA (CVE-2017-15361) fingerprint test.
var rocaPrimes = [...]int64{
	11, 13, 17, 19, 37, 53, 61, 71, 73,
	79, 97, 103, 107, 109, 127, 151, 157,
}

// rocaPrints[i] has bit r set when r is in the subgroup generated by 65537
// modulo rocaPrimes[i].
var rocaPrints [len(rocaPrimes)]*big.Int

func init() {
	for i, p := range rocaPrimes {
		mask := new(big.Int)
		for r := int64(1); ; {
			mask.SetBit(mask, int(r), 1)
			r = r * 65537 % p
			if r == 1 {
				break
			}
		}
		rocaPrints[i] = mask
	}
}

// IsROCAWeak reports whether n carries the ROCA fingerprint: n modulo each
// prime of rocaPrimes lies in the subgroup generated by 65537.
// A nil or non-positive n is not weak.
func IsROCAWeak(n *big.Int) bool {
	if n == nil || n.Sign() <= 0 {
		return false
	}
	rem := new(big.Int)
	for i, p := range rocaPrimes {
		r := rem.Mod(n, big.NewInt(p)).Int64()
		if rocaPrints[i].Bit(int(r)) == 0 {
			return false
		}
	}
	return true
}
